using IndieRun;
using System.IO;
using System.Reflection;
using System.Text.Json;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Markup;
using System.Windows.Threading;
using System.Xml.Linq;

public static class Program
{
    static void Check(bool value,string message){if(!value)throw new Exception(message);}
    static object? Call(object target,string name,params object?[] args)=>target.GetType().GetMethod(name,BindingFlags.Instance|BindingFlags.NonPublic)!.Invoke(target,args);
    static T Get<T>(object target,string name)=>(T)target.GetType().GetField(name,BindingFlags.Instance|BindingFlags.NonPublic|BindingFlags.Public)!.GetValue(target)!;
    static void Set(object target,string name,object? value)=>target.GetType().GetField(name,BindingFlags.Instance|BindingFlags.NonPublic|BindingFlags.Public)!.SetValue(target,value);
    static T Wait<T>(Task<T> task){Wait((Task)task);return task.Result;}
    static void Wait(Task task){var frame=new DispatcherFrame();task.ContinueWith(_=>Application.Current.Dispatcher.BeginInvoke(new Action(()=>frame.Continue=false)));Dispatcher.PushFrame(frame);task.GetAwaiter().GetResult();}
    static IEnumerable<T> Find<T>(DependencyObject root) where T:DependencyObject {if(root is T item)yield return item;foreach(var child in LogicalTreeHelper.GetChildren(root).OfType<DependencyObject>())foreach(var match in Find<T>(child))yield return match;}
    [STAThread] public static int Main(string[] args)
    {
        var app=new Application {ShutdownMode=ShutdownMode.OnExplicitShutdown};var styles=XDocument.Load(Path.Combine(AppContext.BaseDirectory,"styles-source.xaml")).Root!.Elements().Single().Elements().Single();app.Resources=(ResourceDictionary)XamlReader.Parse(styles.ToString(),new ParserContext {BaseUri=new Uri(AppContext.BaseDirectory)});
        SynchronizationContext.SetSynchronizationContext(new DispatcherSynchronizationContext(app.Dispatcher));
        var root=Path.Combine(Path.GetFullPath(args[0]),"run-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);var results=new List<object>();int failures=0;
        void Test(string name,Action test){try{test();results.Add(new{name,status="PASS"});Console.WriteLine("PASS: "+name);}catch(Exception ex){failures++;results.Add(new{name,status="FAIL",error=ex.ToString()});Console.WriteLine("FAIL: "+name+" "+ex.Message);}}
        string Folder(string name){var p=Path.GetFullPath(Path.Combine(root,name));Directory.CreateDirectory(p);File.WriteAllText(Path.Combine(p,"Game.exe"),"fixture");return p;}
        var a=Folder("A/One");var b=Folder("B/Two");var off=Folder("Disabled/Three");var detached=Path.Combine(root,"detached");var library=Path.Combine(root,"library");
        var tags=new TagCatalog {Tags=[new(){Id=Guid.NewGuid().ToString("N"),Kind="genre",Name="퍼즐"},new(){Id=Guid.NewGuid().ToString("N"),Kind="category",Name="짧은 게임"}]};
        Package Game(string path)=>new(){Id=Guid.NewGuid().ToString("N"),IsReal=true,Source=path,DetectedRoot=path,SearchRoot=Path.GetDirectoryName(path)!,Folder=Path.GetFileName(path),Name=Path.GetFileName(path),Alias="별칭 "+Path.GetFileName(path),Genres=["퍼즐"]};
        var games=new List<Package>{Game(a),Game(b),Game(off),Game(Path.Combine(detached,"Four"))};games[0].Categories.Add("짧은 게임");
        var locations=new List<SearchLocation>{new(){Path=Path.Combine(root,"A")},new(){Path=Path.Combine(root,"B")},new(){Path=Path.Combine(root,"Disabled"),Enabled=false},new(){Path=detached}};
        var w=new MainWindow();
        Test("first-run-does-not-auto-select-development-fixture",()=>{Wait((Task)Call(w,"ScanDefaultAsync")!);Check(Get<List<SearchLocation>>(w,"searchLocations").Count==0&&Get<ScanSnapshot?>(w,"snapshot")==null,"Implicit search selected");});
        Test("legacy-single-root-migrates-without-game-mutation",()=>{var doc=new WorkspaceDocument {SearchRoot=root,Destination=library,Packages=games,Tags=tags.Tags};Call(w,"ApplyWorkspace",doc);var migrated=Get<List<SearchLocation>>(w,"searchLocations");Check(migrated.Count==1&&migrated[0].Path==root&&migrated[0].Enabled&&Get<List<Package>>(w,"packages")[0].Alias==games[0].Alias,"Migration failed");});
        Test("location-overlap-add-merges-and-subfolder-does-not-duplicate",()=>{var list=new List<SearchLocation>{new(){Path=a}};Check(SearchLocationRules.Add(list,Path.Combine(root,"A"))&&list.Count==1,"Parent merge failed");Check(!SearchLocationRules.Add(list,a)&&list.Count==1,"Nested duplicate");Check(SearchLocationRules.MinimalRoots([root,root+"\\",a,b]).Count==1,"Normalization loses root");});
        Test("location-state-survives-workspace-roundtrip",()=>{var doc=new WorkspaceDocument {SearchRoot=root,SearchLocations=locations,Destination=library,Packages=games,Tags=tags.Tags};var store=new WorkspaceStore(Path.Combine(root,"workspace.json"));store.Save(doc);var saved=store.Load().Document!;Check(saved.SearchLocations!.Count==4&&!saved.SearchLocations[2].Enabled,"State lost");});
        Set(w,"searchLocations",locations);Set(w,"source",root);Set(w,"destination",library);Set(w,"backupStorageRoot",Path.Combine(root,"backups"));Set(w,"catalog",tags);Set(w,"packages",games);
        ScanSnapshot scan=null!;
        Test("multiple-roots-discover-without-reading-disabled-or-offline",()=>{scan=Wait((Task<ScanSnapshot>)Call(w,"ReadWorkspaceFolders",root,games,CancellationToken.None)!);var found=WorkspaceReconciler.Discover(scan,[]);Check(found.Count==2&&!scan.Files.Any(f=>GameScanner.Within(f.Path,off)),"Wrong discovery scope");Check(found.Single(g=>g.Source==b).SearchRoot==Path.Combine(root,"B"),"Secondary root boundary lost");Check(scan.OfflineRoots.Contains(detached),"Offline not recorded");});
        Test("inactive-and-offline-packages-keep-identity-alias-and-tags",()=>{var id=games[2].Id;WorkspaceReconciler.Check(games[2],null,scan);WorkspaceReconciler.Check(games[3],null,scan);Check(games[2].ReviewState=="paused"&&games[2].Id==id&&games[2].Genres.Contains("퍼즐")&&games[3].ReviewReason.Contains("연결"),"Metadata or availability wrong");});
        Test("unavailable-library-game-is-not-reclassified-as-identity-missing",()=>{var g=games[3];var doc=new LibraryDocument {Games=[new(){Id=g.Id,Folder=g.Folder,LastKnownPath=g.Source}]};new LibraryStore(library).Reconcile(doc,new(),scan);IdentityReconciler.Flag(g,new(),doc);Check(doc.Games[0].Status=="Unavailable"&&g.ReviewState=="offline","Offline identity overwritten");});
        Test("disconnected-location-recovers-on-next-scan",()=>{var folder=Folder("detached/Four");var next=Wait((Task<ScanSnapshot>)Call(w,"ReadWorkspaceFolders",root,games,CancellationToken.None)!);var baseline=WorkspaceReconciler.Capture(games[3],next);WorkspaceReconciler.Check(games[3],baseline,next);Check(next.Files.Any(f=>f.Path==Path.Combine(folder,"Game.exe"))&&games[3].ReviewState=="","Reconnect failed");});
        Test("removed-location-is-not-silently-scanned-through-known-games",()=>{Set(w,"searchLocations",new List<SearchLocation>{locations[0]});var next=Wait((Task<ScanSnapshot>)Call(w,"ReadWorkspaceFolders",root,games,CancellationToken.None)!);Check(!next.Files.Any(f=>GameScanner.Within(f.Path,b))&&next.InactivePaths.Contains(b),"Removed path scanned");Set(w,"searchLocations",locations);});
        Test("paused-search-does-not-report-a-false-access-error",()=>{games[0].ReviewState="paused";var result=GameLaunch.Inspect(games[0],new(){Id=games[0].Id});Check(result.Problem==LaunchProblem.Setup,"Paused location prevents ordinary launch setup");Check(GameLaunch.Inspect(games[0],new(){Id=games[0].Id,Executable="Game.exe"}).Problem==LaunchProblem.None,"Paused search blocks configured executable");games[0].ReviewState="offline";Check(GameLaunch.Inspect(games[0],new(){Id=games[0].Id}).Problem==LaunchProblem.LocationOffline,"Offline is not distinguished");games[0].ReviewState="";});
        Test("explicit-empty-location-list-stays-empty",()=>{Call(w,"ApplyWorkspace",new WorkspaceDocument {SearchRoot=root,SearchLocations=[],Destination=library,Packages=games,Tags=tags.Tags});Check(Get<List<SearchLocation>>(w,"searchLocations").Count==0,"Empty list remigrated");Set(w,"searchLocations",locations);});
        Test("hidden-games-excluded-from-all-favorites-and-recent",()=>{var play=new GamePlay {Id=games[0].Id,Hidden=true,Favorite=true,LastPlayedUtc=DateTime.UtcNow};foreach(var group in new[]{"all","favorites","recent"})Check(!PlayerRules.Matches(games[0],play,new(){Group=group},tags.Tags),"Hidden leaked into "+group);Check(PlayerRules.Matches(games[0],play,new(){Group="hidden"},tags.Tags),"Hidden view empty");});
        Test("hidden-state-persists-and-legacy-default-is-visible",()=>{Directory.CreateDirectory(library);var store=new PlayerStore(library);store.Save(new(){Games=[new(){Id=games[0].Id,Hidden=true}]});Check(store.Load().Games.Single().Hidden,"Hidden not persisted");Check(!JsonSerializer.Deserialize<GamePlay>("{\"Id\":\""+games[1].Id+"\"}")!.Hidden,"Legacy defaults hidden");});
        Test("batch-change-counts-and-keep-add-remove-results",()=>{var genre=tags.Tags[0];var category=tags.Tags[1];Check(TagBatchRules.Present(games,genre)==4&&TagBatchRules.Affected(games,category,true)==3&&TagBatchRules.Affected(games,category,false)==1,"Wrong affected counts");var clone=JsonSerializer.Deserialize<List<Package>>(JsonSerializer.Serialize(games))!;foreach(var p in clone)PlayerRules.ApplyTags(p,tags.Tags,new HashSet<string>{category.Id},new HashSet<string>{genre.Id});Check(clone.All(p=>p.Categories.Contains(category.Name)&&p.Genres.Count==0)&&games.All(p=>p.Genres.Count==1),"Draft or apply wrong");});
        Set(w,"playerRoot",library);Set(w,"playerDocument",new PlayerDocument {Games=games.Select(p=>new GamePlay {Id=p.Id}).ToList()});Set(w,"playerView",new PlayerView());Set(w,"multiSelect",true);Call(w,"SetPage","play");Call(w,"RenderPlayer");
        Test("card-selection-keeps-frame-size-and-uses-no-checkbox",()=>{var cards=Get<WrapPanel>(w,"playerCards");var before=(Border)cards.Children[0];before.Measure(new Size(240,166));var size=before.DesiredSize;Get<HashSet<string>>(w,"playerSelection").Add(((IEnumerable<Package>)Call(w,"VisibleGames")!).First().Id);Call(w,"RenderPlayerItems");var after=(Border)cards.Children[0];after.Measure(new Size(240,166));Check(before.BorderThickness==after.BorderThickness&&size==after.DesiredSize&&!Find<CheckBox>(after).Any(),"Selection changes layout or uses checkbox");Check(Find<TextBlock>(after).Any(t=>t.Text.Contains("선택됨")),"Missing selected label");});
        Test("selection-count-and-actions-have-separate-aligned-columns",()=>{var bar=Get<StackPanel>(w,"selectionBar");var grid=Find<Grid>(bar).First();grid.Measure(new Size(1000,300));grid.Arrange(new Rect(0,0,1000,grid.DesiredSize.Height));var count=(TextBlock)grid.Children[0];var actions=(WrapPanel)grid.Children[1];Check(count.TranslatePoint(new Point(),grid).X+count.ActualWidth<=actions.TranslatePoint(new Point(),grid).X&&count.VerticalAlignment==VerticalAlignment.Center,"Overlapping toolbar");});
        Test("hide-and-unhide-preserve-alias-and-tags",()=>{Set(w,"sessionReady",false);var before=JsonSerializer.Serialize(games.Select(p=>new{p.Id,p.Alias,p.Genres,p.Categories}));var doc=Get<PlayerDocument>(w,"playerDocument");doc.Games[0].Hidden=true;Call(w,"RenderPlayerItems");Check(Get<TextBlock>(w,"playerCount").Text.StartsWith("게임 3개"),"Hidden still visible");Get<PlayerView>(w,"playerView").Group="hidden";Call(w,"RenderPlayerItems");Check(Get<TextBlock>(w,"playerCount").Text.StartsWith("게임 1개")&&before==JsonSerializer.Serialize(games.Select(p=>new{p.Id,p.Alias,p.Genres,p.Categories})),"Metadata changed");});
        Set(w,"closingWithoutSave",true);w.Close();File.WriteAllText(Path.GetFullPath(args[1]),JsonSerializer.Serialize(new{root,total=results.Count,passed=results.Count-failures,failed=failures,results},new JsonSerializerOptions{WriteIndented=true}));Console.WriteLine($"RESULT: {results.Count-failures}/{results.Count}");return failures==0?0:1;
    }
}

